-- ════════════════════════════════════════════════════════════════════
-- Madras Cloth Emporium — one-time database setup for Supabase
-- Paste this whole file into Supabase → SQL Editor → New query → Run.
-- Creates all tables, enables Row Level Security, records the migrations
-- (so 'npm run db:migrate' stays in sync later), and loads 5 categories
-- + 64 clearly-labelled DEMO products. Safe: runs in one transaction.
-- Generated from drizzle/0000_init.sql + 0001_enable_rls.sql + demo seed.
-- ════════════════════════════════════════════════════════════════════
BEGIN;

CREATE TYPE "public"."enquiry_status" AS ENUM('new', 'in_progress', 'closed');
CREATE TYPE "public"."enquiry_type" AS ENUM('contact', 'wedding', 'bulk', 'tailoring', 'product');
CREATE TYPE "public"."order_status" AS ENUM('pending', 'confirmed', 'packed', 'shipped', 'delivered', 'completed', 'cancelled');
CREATE TYPE "public"."payment_status" AS ENUM('unpaid', 'partially_paid', 'paid', 'refunded');
CREATE TYPE "public"."product_status" AS ENUM('draft', 'active', 'archived');
CREATE TYPE "public"."sale_unit" AS ENUM('piece', 'metre');
CREATE TABLE "categories" (
	"id" serial PRIMARY KEY NOT NULL,
	"slug" text NOT NULL,
	"name" text NOT NULL,
	"tagline" text DEFAULT '' NOT NULL,
	"description" text DEFAULT '' NOT NULL,
	"default_sale_unit" "sale_unit" DEFAULT 'piece' NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	CONSTRAINT "categories_slug_unique" UNIQUE("slug")
);

CREATE TABLE "customers" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"auth_user_id" text,
	"name" text NOT NULL,
	"phone" text NOT NULL,
	"email" text,
	"loyalty_balance" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "customers_auth_user_id_unique" UNIQUE("auth_user_id"),
	CONSTRAINT "customers_phone_unique" UNIQUE("phone")
);

CREATE TABLE "enquiries" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"type" "enquiry_type" NOT NULL,
	"status" "enquiry_status" DEFAULT 'new' NOT NULL,
	"name" text NOT NULL,
	"phone" text NOT NULL,
	"email" text,
	"city" text,
	"message" text,
	"details" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"product_id" uuid,
	"admin_notes" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "loyalty_ledger" (
	"id" serial PRIMARY KEY NOT NULL,
	"customer_id" uuid NOT NULL,
	"order_id" uuid,
	"points" integer NOT NULL,
	"reason" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "order_events" (
	"id" serial PRIMARY KEY NOT NULL,
	"order_id" uuid NOT NULL,
	"status" "order_status" NOT NULL,
	"note" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "order_items" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"order_id" uuid NOT NULL,
	"product_id" uuid,
	"variant_id" uuid,
	"product_name" text NOT NULL,
	"product_slug" text NOT NULL,
	"variant_label" text,
	"sale_unit" "sale_unit" NOT NULL,
	"quantity" numeric(10, 2) NOT NULL,
	"unit_price_paise" integer NOT NULL,
	"line_total_paise" integer NOT NULL,
	"is_demo" boolean DEFAULT false NOT NULL,
	"hsn_code" text,
	"gst_rate_pct" numeric(5, 2)
);

CREATE TABLE "orders" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"order_number" text NOT NULL,
	"status" "order_status" DEFAULT 'pending' NOT NULL,
	"channel" text DEFAULT 'whatsapp' NOT NULL,
	"fulfilment" text DEFAULT 'delivery' NOT NULL,
	"customer_id" uuid,
	"customer_name" text NOT NULL,
	"phone" text NOT NULL,
	"email" text,
	"address_line" text,
	"city" text,
	"state" text,
	"pincode" text,
	"customer_notes" text,
	"admin_notes" text,
	"subtotal_paise" integer NOT NULL,
	"shipping_paise" integer DEFAULT 0 NOT NULL,
	"discount_paise" integer DEFAULT 0 NOT NULL,
	"total_paise" integer NOT NULL,
	"contains_demo_items" boolean DEFAULT false NOT NULL,
	"stock_deducted" boolean DEFAULT false NOT NULL,
	"payment_status" "payment_status" DEFAULT 'unpaid' NOT NULL,
	"payment_provider" text,
	"payment_ref" text,
	"courier" text,
	"tracking_number" text,
	"invoice_number" text,
	"loyalty_points_earned" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "orders_order_number_unique" UNIQUE("order_number")
);

CREATE TABLE "product_variants" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"product_id" uuid NOT NULL,
	"sku" text,
	"option_type" text DEFAULT 'size' NOT NULL,
	"label" text NOT NULL,
	"price_paise" integer,
	"stock_qty" numeric(10, 2) DEFAULT 0 NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL
);

CREATE TABLE "products" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"slug" text NOT NULL,
	"sku" text,
	"name" text NOT NULL,
	"category_id" integer NOT NULL,
	"short_description" text DEFAULT '' NOT NULL,
	"description" text DEFAULT '' NOT NULL,
	"fabric" text DEFAULT '' NOT NULL,
	"colour" text DEFAULT '' NOT NULL,
	"occasion" text DEFAULT '' NOT NULL,
	"work" text DEFAULT '' NOT NULL,
	"width_inches" integer,
	"care" text DEFAULT '' NOT NULL,
	"sale_unit" "sale_unit" DEFAULT 'piece' NOT NULL,
	"price_paise" integer NOT NULL,
	"mrp_paise" integer,
	"min_qty" numeric(8, 2) DEFAULT 1 NOT NULL,
	"qty_step" numeric(8, 2) DEFAULT 1 NOT NULL,
	"stock_qty" numeric(10, 2) DEFAULT 0 NOT NULL,
	"track_stock" boolean DEFAULT true NOT NULL,
	"low_stock_threshold" numeric(8, 2) DEFAULT 3 NOT NULL,
	"is_demo" boolean DEFAULT false NOT NULL,
	"status" "product_status" DEFAULT 'draft' NOT NULL,
	"featured" boolean DEFAULT false NOT NULL,
	"tags" text[] DEFAULT '{}' NOT NULL,
	"images" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"attributes" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"art_pattern" text DEFAULT 'buti' NOT NULL,
	"art_colors" text[] DEFAULT '{}' NOT NULL,
	"hsn_code" text,
	"gst_rate_pct" numeric(5, 2),
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "products_slug_unique" UNIQUE("slug")
);

CREATE TABLE "rate_limits" (
	"key" text PRIMARY KEY NOT NULL,
	"window_start" timestamp with time zone DEFAULT now() NOT NULL,
	"count" integer DEFAULT 0 NOT NULL
);

ALTER TABLE "enquiries" ADD CONSTRAINT "enquiries_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "public"."products"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "loyalty_ledger" ADD CONSTRAINT "loyalty_ledger_customer_id_customers_id_fk" FOREIGN KEY ("customer_id") REFERENCES "public"."customers"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "loyalty_ledger" ADD CONSTRAINT "loyalty_ledger_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."orders"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "order_events" ADD CONSTRAINT "order_events_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."orders"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."orders"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "public"."products"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "order_items" ADD CONSTRAINT "order_items_variant_id_product_variants_id_fk" FOREIGN KEY ("variant_id") REFERENCES "public"."product_variants"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "orders" ADD CONSTRAINT "orders_customer_id_customers_id_fk" FOREIGN KEY ("customer_id") REFERENCES "public"."customers"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "product_variants" ADD CONSTRAINT "product_variants_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "public"."products"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "products" ADD CONSTRAINT "products_category_id_categories_id_fk" FOREIGN KEY ("category_id") REFERENCES "public"."categories"("id") ON DELETE restrict ON UPDATE no action;
CREATE INDEX "enquiries_type_idx" ON "enquiries" USING btree ("type");
CREATE INDEX "enquiries_status_idx" ON "enquiries" USING btree ("status");
CREATE INDEX "order_events_order_idx" ON "order_events" USING btree ("order_id");
CREATE INDEX "order_items_order_idx" ON "order_items" USING btree ("order_id");
CREATE INDEX "orders_status_idx" ON "orders" USING btree ("status");
CREATE INDEX "orders_phone_idx" ON "orders" USING btree ("phone");
CREATE INDEX "variants_product_idx" ON "product_variants" USING btree ("product_id");
CREATE INDEX "products_category_idx" ON "products" USING btree ("category_id");
CREATE INDEX "products_status_idx" ON "products" USING btree ("status");
CREATE INDEX "products_price_idx" ON "products" USING btree ("price_paise");
-- Lock every table away from Supabase's auto-generated public API (anon/authenticated roles).
-- The app connects as the database owner via DATABASE_URL, which bypasses RLS.
-- When customer accounts arrive, add explicit policies per table instead of disabling RLS.
ALTER TABLE "categories" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "products" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "product_variants" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "customers" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "orders" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "order_items" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "order_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "enquiries" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "loyalty_ledger" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "rate_limits" ENABLE ROW LEVEL SECURITY;

-- Migration bookkeeping (matches drizzle's migrator)
CREATE SCHEMA IF NOT EXISTS drizzle;
CREATE TABLE IF NOT EXISTS drizzle.__drizzle_migrations (id SERIAL PRIMARY KEY, hash text NOT NULL, created_at bigint);
INSERT INTO drizzle.__drizzle_migrations (hash, created_at) VALUES ('8e8052ca8c735cf39eaa06dc3fe61b9acafa38b7230650aa4dbb9aab7fbdec39', 1794140233588);
INSERT INTO drizzle.__drizzle_migrations (hash, created_at) VALUES ('0e11a325bef9ac266a01ec90be9a1b4f0e291ac60addc0eb9520b5de1839f17d', 1794140271114);

