INSERT INTO public.categories (id, slug, name, tagline, description, default_sale_unit, sort_order) VALUES (1, 'sarees', 'Sarees', 'Six yards of celebration', 'Silk, cotton, georgette and chiffon sarees for weddings, festivals and everyday grace — chosen with the eye of a family that has dressed Bokaro since 1970.', 'piece', 1);
INSERT INTO public.categories (id, slug, name, tagline, description, default_sale_unit, sort_order) VALUES (2, 'suits-dress-materials', 'Suits & Dress Materials', 'Unstitched sets, made yours', 'Three-piece dress materials and suit sets in cotton, chanderi, georgette and silk blends — ready for your tailor, or ours.', 'piece', 2);
