INSERT INTO public.categories (id, slug, name, tagline, description, default_sale_unit, sort_order) VALUES (4, 'shirting-fabrics', 'Shirting Fabrics', 'Crisp cloth, cut by the metre', 'Cotton, linen and blended shirting in solids, stripes and checks — sold by the metre for your tailor.', 'metre', 4);
INSERT INTO public.categories (id, slug, name, tagline, description, default_sale_unit, sort_order) VALUES (5, 'suiting-fabrics', 'Suiting Fabrics', 'Tailoring begins with cloth', 'Terry-rayon, poly-viscose and wool-blend suiting for suits, trousers and safari sets — sold by the metre.', 'metre', 5);
